function Queue:push(value)
local size, cap = self.size, self.cap

if size == cap then
self:resize(cap * 2)
cap = self.cap
end
local tail = self.tail + 1
if tail > cap then
tail = 1
end
self.tail = tail
self.data[tail] = value
self.size = size + 1
