end

function Queue:pop()
if self.size == 0 then
return nil
end
local head = self.head
local value = self.data[head]
self.data[head] = nil
head = head + 1
if head > self.cap then
head = 1
end
self.head = head
self.size = self.size - 1

local cap = self.cap
if self.size * 4 <= cap and cap > self.min_cap then
