local old = self.data
local old_head = self.head
local old_cap = self.cap
local size = self.size
local new = new_data(new_cap)
for i = 1, size do
new[i] = old[old_head]
old[old_head] = nil
old_head = old_head + 1
if old_head > old_cap then
old_head = 1
end
end
self.data = new
self.head = 1
self.tail = size
self.cap = new_cap
end

