if other == nil or other.size == 0 then
return 0
end
local moved = 0
local head = other.head
local cap = other.cap
for i = 1, other.size do
self:push(other.data[head])
head = head + 1
if head > cap then
head = 1
end
moved = moved + 1
end
other:clear()
return moved
end

