}
elseif kind == "waitSignal" or kind == "emitSignal" or kind == "emitPulse" then

return {
kind = kind,
machineSignalIndex = Util.int(el.machineSignalIndex, 1),
sides = normalizeSides(el.sides),
threshold = Util.clamp(Util.num(el.threshold, 0), 0, 15),
