}
elseif kind == "filters" then
local rules = {}
for _, rule in ipairs(obj.rules or {}) do
if type(rule) == "table" then
rules[#rules + 1] = {
type = rule.type,
id = rule.id or "",
nbt = rule.nbt or "",
ignoreNbt = rule.ignoreNbt == true,
}
end
end
return {
name = name,
rules = rules,
}
elseif kind == "machineTypes" then
return {
name = name,
}
elseif kind == "machines" then
return {
