        print("[IFM] created directory: " .. baseDir)
    end
    --- 先删掉自己再解压（CC:T 的磁盘很小）：产物本身有几百 KB，和"解压出来的 18 个文件"同时存在
    --- 很容易超出磁盘容量（运行时报 out of space 而半途而废）。源码此刻已全部读进内存，
    --- 删掉磁盘上的产物文件不影响这次解压 —— 只是不能再"重跑一次解压"了（重新下载即可）。
    --- 注意：本产物被命名为 IFMMaster.lua / IFMWorker.lua / IFMCrafter.lua 时不删（它是入口本体）。
    local isEntryName = (programPath == "IFMMaster.lua" or programPath == "IFMWorker.lua"
        or programPath == "IFMCrafter.lua")
    if fs.exists(program) and not isEntryName then
        local removed, removeErr = pcall(fs.delete, program)
        if removed then
            print("[IFM] unpacker deleted first (frees disk space before unpacking): " .. program)
        else
            print("[IFM] note: could not delete the unpacker now (" .. tostring(removeErr) ..
                ") - unpacking anyway")
        end
    end
    local created, updated, unchanged, skipped = 0, 0, 0, 0
    for relative, content in pairs(__IFM_FILES) do
        local path = fs.combine(baseDir, relative)
        if __ifm_normalizePath(path) == programPath then
            -- do not overwrite the file that is currently running
            skipped = skipped + 1
        else
            local folder = fs.getDir(path)
            if folder ~= "" and not fs.exists(folder) then
                fs.makeDir(folder)
            end
            local current = nil
            if fs.exists(path) then
                local handle = fs.open(path, "r")
                if handle then
                    current = handle.readAll()
                    handle.close()
                end
            end
            if current == content then
                unchanged = unchanged + 1
            else
                local handle = fs.open(path, "w")
                if not handle then
                    error("Cannot write " .. path, 0)
                end
                handle.write(content)
                handle.close()
                if current then
                    updated = updated + 1
                else
                    created = created + 1
                end
            end
        end
    end
    print(("[IFM] unpack: %d created, %d updated, %d unchanged, %d skipped"):format(
        created, updated, unchanged, skipped))
    print("[IFM] entry file: " .. fs.combine(baseDir, "IFMMaster.lua"))
    print("[IFM] start the server with: " .. fs.combine(baseDir, "IFMMaster.lua"))
    --- 老布局（<= 1.6.16）提醒：入口在产物同级、模块在 ifm/*.lua 里，别继续用旧入口启动
    local legacyEntry = fs.combine(bundleDir, "IFMMaster.lua")
    if fs.exists(legacyEntry) then
        print("[IFM] note: old layout detected (" .. legacyEntry .. "). " ..
            "The new entry is " .. fs.combine(baseDir, "IFMMaster.lua") ..
            "; the old file and the old ifm/*.lua modules are leftovers you can delete.")
    end
    local legacyData = fs.combine(baseDir, "config.json")
    if fs.exists(legacyData) then
        print("[IFM] note: legacy data found at " .. legacyData ..
            " - the master migrates it to " .. fs.combine(baseDir, "data", "config.json") .. " on startup.")
    end
    return baseDir
end

-- ===== 解压（本产物只解压，不会自启服务端） =====
local __ifm_base = __ifm_unpack()
__IFM_FILES = nil

if select("#", ...) > 0 then
    print("[IFM] note: this bundle only unpacks; arguments are ignored (pass them to IFMMaster.lua)")
end

-- ===== 解压完成后删除本产物自身 =====
local __ifm_self = (shell and shell.getRunningProgram and shell.getRunningProgram()) or nil
local __ifm_entry = __ifm_normalizePath(fs.combine(__ifm_base, "IFMMaster.lua"))
local __ifm_worker = __ifm_normalizePath(fs.combine(__ifm_base, "IFMWorker.lua"))
local __ifm_crafter = __ifm_normalizePath(fs.combine(__ifm_base, "IFMCrafter.lua"))
if __ifm_self == nil then
    print("[IFM] warning: cannot locate this file, please delete it manually")
elseif not fs.exists(__ifm_self) then
    -- `wget run <url>` / `pastebin run ...` 这类“直接从 URL 跑”的情况：磁盘上根本没有这个文件，
    -- 没有东西可删（也不要打印“删不掉”的警告）。（1.6.13）
    print("[IFM] nothing to delete now (run from a URL, or already removed before unpacking)")
elseif __ifm_normalizePath(__ifm_self) == __ifm_entry
    or __ifm_normalizePath(__ifm_self) == __ifm_worker
    or __ifm_normalizePath(__ifm_self) == __ifm_crafter then
    -- 本产物被命名为入口文件名（IFMMaster.lua / IFMWorker.lua / IFMCrafter.lua）：它就是入口本体
    print("[IFM] this file is named IFMMaster.lua / IFMWorker.lua / IFMCrafter.lua, keeping it (it is an entry point)")
else
    local okDelete, deleteErr = pcall(fs.delete, __ifm_self)
    if okDelete then
        print("[IFM] unpacker deleted: " .. fs.combine(__ifm_self))
    else
        print("[IFM] warning: could not delete " .. fs.combine(__ifm_self) .. " (" .. tostring(deleteErr) .. ")")
    end
end

print("[IFM] unpack finished - the server was NOT started by this file.")
print("[IFM] start it with: IFMMaster.lua [--room <room>] [--relay <ws-base-url>] [--random-room]")
